script:
(function () {
  "use strict";

  var loginTabEl = document.getElementById("login-tab");
  var signupTabEl = document.getElementById("signup-tab");
  var emailEl = document.getElementById("login-email");
  var passwordEl = document.getElementById("login-password");
  var submitEl = document.getElementById("login-submit");
  var messageEl = document.getElementById("auth-message");
  var forgotPasswordEl = document.getElementById("forgot-password");

  var mode = "login";


  if (messageEl) {
    messageEl.textContent = "";
    messageEl.style.display = "none";
  }


  function setMode(m) {
    mode = m;

    if (loginTabEl && signupTabEl) {
      if (mode === "login") {
        loginTabEl.style.backgroundColor = "#ffffff";
        loginTabEl.style.opacity = "1";
        loginTabEl.style.boxShadow= "0 0 1.5px 0 rgba(0, 0, 0, 0.16), 0 2px 5px 0 rgba(0, 0, 0, 0.14)"
        loginTabEl.style.color= "var(--ink-gray-8)"
        signupTabEl.style.backgroundColor = "transparent";
        signupTabEl.style.opacity = "0.5";
        signupTabEl.style.boxShadow="none";
        signupTabEl.style.color= "var(--ink-gray-6)"
      } else {
        signupTabEl.style.backgroundColor = "#ffffff";
        signupTabEl.style.opacity = "1";
        signupTabEl.style.boxShadow="0 0 1.5px 0 rgba(0, 0, 0, 0.16), 0 2px 5px 0 rgba(0, 0, 0, 0.14)"
        signupTabEl.style.color= "var(--ink-gray-8)"
        loginTabEl.style.backgroundColor = "transparent";
        loginTabEl.style.opacity = "0.5";
        loginTabEl.style.boxShadow="none";
        loginTabEl.style.color= "var(--ink-gray-6)"
      }
    }

    var passwordContainer = passwordEl.parentElement;
    if (passwordContainer) {
      passwordContainer.style.display = mode === "login" ? "" : "none";
    }

    var submitTextEl = submitEl.querySelector("p");
    if (submitTextEl) {
      submitTextEl.textContent = mode === "login" ? "Login" : "Sign up";
    } else {
      submitEl.textContent = mode === "login" ? "Login" : "Sign up";
    }
  }

  if (loginTabEl) {
    loginTabEl.addEventListener("click", function (e) {
      e.preventDefault();
      setMode("login");
    });
  }
  if (signupTabEl) {
    signupTabEl.addEventListener("click", function (e) {
      e.preventDefault();
      setMode("signup");
    });
  }

  function showMessage(msg, isError) {
    if (!messageEl) return;

    var pEl = messageEl.querySelector("p") || messageEl;
    pEl.textContent = msg;

    messageEl.style.display = "block";
    messageEl.style.color = isError ? "#ef4444" : "#16a34a";
  }

  function getFullNameFromEmail(email) {
    var localPart = email.split("@")[0];
    var parts = localPart.split(/[._-]/);
    var formattedParts = parts.map(function (part) {
      return part.charAt(0).toUpperCase() + part.slice(1);
    });
    return formattedParts.join(" ");
  }

  function isValidEmail(email) {
    var re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  }

  function validate(email, password) {
    if (!email || !isValidEmail(email)) {
      return "Please enter a valid email address.";
    }
    if (mode === "login" && !password) {
      return "Please enter your password.";
    }
    return null;
  }

  async function handleSubmit(e) {
    if (e) e.preventDefault();

    var email = (emailEl.value || "").trim();
    var password = (passwordEl.value || "").trim();

    var errorMsg = validate(email, password);
    if (errorMsg) {
      showMessage(errorMsg, true);
      return;
    }

    showMessage(mode === "login" ? "Logging in..." : "Signing up...", false);

    var urlParams = new URLSearchParams(window.location.search);
    var redirectTo = urlParams.get("redirect-to") || urlParams.get("redirect_to") || "/cafe";

    try {
      if (mode === "login") {
        await window.frappeClient.call("login", {
          usr: email,
          pwd: password
        });
        showMessage("Login successful! Redirecting...", false);
        window.location.href = redirectTo;
      } else {
        var fullName = getFullNameFromEmail(email);
        await window.frappeClient.call("frappe.core.doctype.user.user.sign_up", {
          email: email,
          full_name: fullName,
          redirect_to: redirectTo
        });
        showMessage("Signup successful! Please check your email to complete registration.", false);
      }
    } catch (err) {
      console.error(err);
      showMessage(err.message || "Authentication failed", true);
    }
  }

  submitEl.addEventListener("click", handleSubmit);
  passwordEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter") {
      handleSubmit(e);
    }
  });
  emailEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter") {
      handleSubmit(e);
    }
  });

  function showDialogError(message) {
    var errorEl = document.querySelector(".frappe-dialog-error");
    if (message) {
      if (!errorEl) {
        errorEl = document.createElement("div");
        errorEl.className = "frappe-dialog-error";
        var body = document.querySelector(".frappe-dialog-body");
        if (body) {
          body.appendChild(errorEl);
        }
      }
      errorEl.textContent = message;
      errorEl.style.display = "block";
    } else if (errorEl) {
      errorEl.style.display = "none";
    }
  }

  if (forgotPasswordEl) {
    forgotPasswordEl.addEventListener("click", function (e) {
      e.preventDefault();

      renderFormDialog({
        title: "Forgot Password",
        saveLabel: "Send Password Reset Link",
        fields: [
          {
            id: "forgot-email",
            label: "Email Address",
            type: "email",
            required: true,
            placeholder: "john@doe.com"
          }
        ],
        onSave: async function (values, close) {
          var email = (values["forgot-email"] || "").trim();
          if (!email || !isValidEmail(email)) {
            showDialogError("Please enter a valid email address.");
            return;
          }
          showDialogError("");

          try {
            await window.frappeClient.call("frappe.core.doctype.user.user.reset_password", {
              user: email
            });
            close();
            showMessage("Password reset link has been sent to your email.", false);
          } catch (err) {
            console.error(err);
            showDialogError(err.message || "Failed to send password reset link");
          }
        }
      });
    });
  }

  setMode("login");
})();
